import React from "react";
import { EmployeeWarning } from "@/types";
import { Panel } from "./Panel";

// What the employee hears for each kind (telephony/asterisk/sounds, generated by make_warning_sounds.py)
const SPOKEN: Record<string, string> = {
  otp: "تنبيه، المتصل بيطلب كود التحقق، متدّيهوش.",
  secret: "تنبيه، المتصل بيطلب بيانات سرية، متقولهاش.",
  payment: "تنبيه، المتصل بيطلب تحويل فلوس، متحوّلش.",
  remote: "تنبيه، المتصل عايزك تنزّل برنامج تحكم، متنزّلوش.",
  impersonation: "تنبيه، المتصل ممكن ينتحل صفة البنك، اتأكد منه.",
  pressure: "تنبيه، المتصل بيضغط عليك، خد وقتك.",
  general: "تنبيه، احتمال نصب في المكالمة، خلّي بالك.",
};

/** Spoken warnings already played into the employee's ear on this call (the caller hears nothing). */
export const EmployeeWarnings: React.FC<{ warnings: EmployeeWarning[] }> = ({ warnings }) => (
  <Panel title="Warnings played to the employee">
    {warnings.length === 0 ? (
      <p className="text-sm text-faint">None yet. Only the employee hears them.</p>
    ) : (
      <ul className="space-y-3">
        {warnings.map((w, i) => (
          <li key={i}>
            <p dir="rtl" className="text-[15px]">{SPOKEN[w.kind] ?? w.kind}</p>
            <p className="text-xs text-faint mt-0.5">
              {w.delayMs != null && `${(w.delayMs / 1000).toFixed(1)} s after the caller's sentence · `}
              {new Date(w.at).toLocaleTimeString()}
            </p>
          </li>
        ))}
      </ul>
    )}
  </Panel>
);
